   111		\uses{def:cl-dist, def:ld-question-distribution, def:ld-line-description, def:line-representative, lem:distribution-map-comp, lem:uniform-map-equivalence, lem:uniform-product-first-marginal, lem:uniform-product-second-marginal, lem:chi-index-uniform, lem:line-representative-idempotent, lem:line-rep-incidence}
